from engine import span
def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='Con Felipe II la Monarquía Hispánica alcanzó, según las fuentes, el apogeo de su influencia y poder, y a la vez acumuló guerras simultáneas y deudas que la dejaron al borde de la quiebra. Este capítulo recorre su reinado a través de cuatro episodios: la unión con Portugal, Lepanto, la Armada de 1588 y las bancarrotas, y propone una regla práctica: contrastar siempre cifras de fuentes distintas.',
        quotes=[Q('es_felipe2','Bajo Felipe II, España alcanzó la cima de su influencia y poder'), Q('en_felipe2','Under Philip II, Spain reached the height of its influence and power')]))
    P.append(dict(text='Felipe II nació en Valladolid el 21 de mayo de 1527, hijo de Carlos I e Isabel de Portugal, y fue rey de España desde 1556 hasta su muerte en 1598, de Nápoles y Sicilia desde 1554 y de Portugal desde 1580. Fue también rey de Inglaterra e Irlanda por su matrimonio con María I, entre 1554 y 1558. Heredó el Imperio español de su padre, y era además duque de Milán desde 1540 y señor de los Países Bajos desde 1555.',
        quotes=[Q('es_felipe2','Valladolid, 21 de mayo de 1527-San Lorenzo de El Escorial, 13 de septiembre de 1598'), Q('en_felipe2','Philip inherited his father\'s Spanish Empire in 1556'), Q('es_felipe2','Fue asimismo rey de Inglaterra e Irlanda iure uxoris, por su matrimonio con María I, entre 1554 y 1558.'), Q('en_felipe2','Further, he was Duke of Milan from 1540. From 1555, he was Lord of the Seventeen Provinces of the Netherlands.')]))
    P.append(dict(text='En 1580 Felipe ascendió al trono portugués tras una crisis dinástica y formó la Unión Ibérica, una unión dinástica que duró sesenta años. Una de las fuentes lo cuenta entre sus logros: aseguró el reino de Portugal y su imperio, y con ellos el conjunto de dominios de Felipe llegó a abarcar territorios en todos los continentes conocidos entonces por los europeos. Como la unión de Castilla y Aragón, fue una unión dinástica.',
        quotes=[Q('es_felipe2','de Portugal y los Algarbes —como Felipe I— desde 1580, logrando una unión dinástica que duró sesenta años'), Q('en_felipe2','He secured the Portuguese kingdom and empire.'), Q('es_felipe2','gobernó territorios en todos los continentes conocidos entonces por los europeos')]))
    P.append(dict(text='Felipe se veía a sí mismo como defensor de la Europa católica frente al Imperio otomano y la Reforma, y empeñó la hegemonía española en varios frentes simultáneos. En los Países Bajos, la decisión de aplicar los acuerdos de Trento provocó un ambiente de revolución que desembocó en la guerra de los Ochenta Años. En 1584 firmó el Tratado de Joinville, por el que financió a la Liga Católica francesa contra los hugonotes durante la década siguiente.',
        quotes=[Q('es_felipe2','Profundamente devoto, Felipe se veía a sí mismo como el defensor de la Europa católica contra el Imperio otomano y la Reforma protestante'), Q('en_felipe2','invested Spain\'s position as the leading European power in multiple simultaneous warring efforts'), Q('es_felipe2','Felipe firmó el Tratado de Joinville, financiando la Liga Católica Francesa durante la década siguiente contra los hugonotes franceses')]))
    P.append(dict(text='La batalla de Lepanto se libró el 7 de octubre de 1571 en el golfo de Patras. La Liga Santa, una coalición católica organizada por el papa Pío V, derrotó a la armada otomana. El mando general lo ejerció Juan de Austria, hermano de Felipe II, y España fue el mayor contribuyente financiero, aunque Venecia aportó más barcos. Fue la mayor batalla naval de la historia occidental desde la Antigüedad clásica y el último gran combate librado casi exclusivamente entre naves de remo, es decir, galeras y galeazas.',
        quotes=[Q('es_lepanto','tuvo lugar el 7 de octubre de 1571 en el golfo de Patras'), Q('en_lepanto','Spain was the largest financial contributor'), Q('en_lepanto','It was the largest naval battle in Western history since classical antiquity'), Q('es_lepanto','Venecia era el principal contribuyente de barcos')]))
    P.append(dict(text='Las cifras de las fuerzas difieren según la fuente. Una cuenta 198 galeras, 11 galeazas, un galeón y 7 naves más, con 1300 cañones y 48 000 hombres; otra, 206 galeras y seis galeazas cristianas. La flota otomana, según la segunda fuente, tenía 211 galeras, 63 galeotas y algunas naves menores. Las diferencias de recuento (galeras entre 198 y 206, galeazas entre 6 y 11) no cambian el resultado, pero sirven de recordatorio de que las cifras de una batalla antigua son estimaciones.',
        quotes=[Q('es_lepanto','En total suman 198 galeras, 11 galeazas, un galeón, 7 naves más, con un total de 1300 cañones y 48 000 hombres'), Q('en_lepanto','The Christian fleet consisted of 206 galleys and six galleasses'), Q('en_lepanto','commanded an Ottoman force of 211 war galleys, 63 galliots, and some smaller vessels')]))
    P.append(dict(text='Las bajas también se estiman de modos distintos. Una fuente cuenta la pérdida de 12 galeras cristianas y de 7600 hombres, de los cuales 2000 eran españoles, 880 de la escuadra papal y 4800 venecianos, y entre 25 000 y 30 000 muertos turcos; la otra, unos 7500 cristianos y 30 000 turcos muertos, y añade que otras fuentes elevan las cifras a 10 000 y 40 000. Obsérvese que las partes de la primera fuente, 2000 + 880 + 4800, suman 7680, ochenta más que el total de 7600 que da.',
        quotes=[Q('es_lepanto','Se contabiliza la pérdida de 12 galeras cristianas','880 de la escuadra del papa y 4800 venecianos'), Q('es_lepanto','Se estimaron entre 25 000 y 30 000 los muertos del bando turco'), Q('en_lepanto','The Christian side suffered around 7,500 deaths, the Turkish side about 30,000.','with 10,000 Christians and 40,000 Ottomans dead')]))
    P.append(dict(text='Las fuentes valoran de modos distintos los efectos de la victoria. Según una de ellas, frenó el expansionismo otomano en el Mediterráneo oriental durante algunas décadas, y los turcos reconstruyeron rápidamente su flota, aunque las pérdidas de tripulaciones experimentadas hicieron que la marina otomana perdiera la iniciativa a partir de la década de 1580. Venecia, por su parte, firmó una paz por separado en 1573 en condiciones de perdedora: cedió Chipre a los otomanos y pagó una indemnización de 300 000 ducados.',
        quotes=[Q('es_lepanto','las enormes pérdidas de tripulaciones experimentadas en Lepanto ocasionaron que la marina otomana perdiera su iniciativa naval a partir de la década de 1580'), Q('en_lepanto','The Ottomans were quick to rebuild their navy.'), Q('en_lepanto','Venice was forced to accept loser\'s terms in spite of the victory at Lepanto.')]))
    P.append(dict(text='En 1588 Felipe envió la Armada, que la tradición llamó Invencible, para invadir la Inglaterra protestante, derrocar a Isabel I y restablecer allí el catolicismo. El plan consistía en que la flota española transportara el ejército de Parma desde los Países Bajos. La flota fue rechazada en una escaramuza y sufrió las tormentas en el retorno. Según una fuente, 87 barcos, unas dos terceras partes de la flota, volvieron a España; según la otra, hasta 24 naves naufragaron por el camino.',
        quotes=[Q('es_felipe2','En 1588 envió la posteriormente conocida como «Armada Invencible» para invadir la Inglaterra protestante','restablecer el catolicismo allí'), Q('en_armada','Philip then formed a more realistic plan: a fleet sailing from Spain would transport Parma\'s army from the Low Countries to England.'), Q('es_armada','87 barcos —unas dos terceras partes de la flota— regresaron a España'), Q('en_armada','Up to 24 ships were wrecked along the way before the rest managed to get home.'), Q('es_felipe2','pero su flota fue rechazada en una escaramuza y naufragó por las tormentas en su retorno a España')]))
    P.append(dict(text='Hay discrepancia sobre el tamaño de la flota. Una fuente habla de 130 barcos al zarpar y, más adelante, de 137 navíos españoles; la otra explica que, tras varias incidencias, quedaron 137 barcos que navegaron hacia el Canal. Casi la mitad no eran buques de guerra: la armada incluía 24 buques de guerra construidos como tales, 44 mercantes armados, 38 buques auxiliares y 34 de aprovisionamiento. El problema resuelto de este capítulo contrasta cuál de las dos cifras, 130 o 137, encaja con la fracción de dos tercios de supervivientes.',
        quotes=[Q('es_armada','La armada incluía 19 000 infantes, 7000 marineros, 1000 caballeros de fortuna, 180 clérigos y 130 barcos'), Q('es_armada','dos galeones de los 137 navíos españoles'), Q('en_armada','leaving 137 ships that sailed for the English Channel'), Q('en_armada','The armada included 24 purpose-built warships, 44 armed merchantmen, 38 auxiliary vessels and 34 supply ships.')]))
    P.append(dict(text='Al año siguiente Inglaterra envió una expedición contra España, la llamada Invencible Inglesa o Contraarmada de 1589, que también fracasó. Felipe envió nuevas armadas en 1596 y 1597, y su hijo otra en 1601, pero todas terminaron igualmente en fracaso. Aun así, una de las fuentes recuerda que, aunque los fracasos de Felipe han sido magnificados por la propaganda hostil, en su momento no provocaron grandes cambios en el equilibrio de poder en Europa.',
        quotes=[Q('es_armada','Esta expedición fue conocida como la Invencible Inglesa, o Contraarmada, y también fracasó en sus objetivos.'), Q('en_armada','Three further Spanish armadas were sent against England and Ireland in 1596, 1597, and 1601, but these likewise ended in fai'), Q('en_felipe2','even though at the time those defeats did not result in great political or military changes in the balance of power in Europe')]))
    P.append(dict(text='Las guerras fueron costosas. Felipe heredó de su padre una deuda de unos veinte millones de ducados y dejó a su sucesor otra que la quintuplicaba. Los ingresos de la Corona se cuadruplicaron durante el reinado, porque la carga fiscal sobre Castilla se cuadruplicó y llegó plata de América, pero no bastaron: se declaró la bancarrota, es decir, se suspendieron los pagos de la deuda, en 1557, 1560, 1569, 1575 y 1596, según las dos fuentes principales. Una sección de una de ellas cuenta solo tres, las de 1557, 1575 y 1596, lo que indica que ese texto no es coherente consigo mismo.',
        quotes=[Q('es_felipe2','Felipe II heredó una deuda de su padre de unos veinte millones de ducados y dejó a su sucesor una que quintuplicaba esta deuda.'), Q('es_felipe2','al final de su reinado eran cuatro veces mayor que cuando comenzó a reinar, pues la carga fiscal sobre Castilla se cuadruplicó y la riqueza procedente de América alcanzó valores históricos'), Q('es_felipe2','llegando a declarar bancarrotas en 1557, 1560, 1569, 1575 y 1596'), Q('en_felipe2','seeing state defaults in 1557, 1560, 1569, 1575, and 1596'), Q('es_felipe2','la Hacienda Real se declaró en bancarrota tres veces (1557, 1575 y 1596)')]))
    P.append(dict(role='definition', text='Bancarrota de la Corona: suspensión de pagos de la deuda real. En 1557, poco después de que Felipe II llegase al poder, la Corona suspendió los pagos de sus deudas, y esta fue la primera de las bancarrotas de su reinado.',
        quotes=[Q('es_felipe2','la Corona hubo de suspender los pagos de sus deudas declarando la primera bancarrota'), Q('en_felipe2','his exchequer several times faced bankruptcy')]))
    P.append(dict(role='consejo', text='Cuando la misma magnitud aparezca con dos valores, compruebe si alguna relación del texto elige uno de ellos. Aquí, la frase «unas dos terceras partes de la flota» permite comparar 87/130 con 87/137 y ver cuál encaja mejor. Es un ejemplo de cómo una verificación aritmética sencilla orienta la crítica de fuentes, sin sustituirla.',
        quotes=[Q('es_armada','87 barcos —unas dos terceras partes de la flota— regresaron a España'), Q('en_armada','leaving 137 ships that sailed for the English Channel')]))
    P.append(dict(role='self_check', text='¿Qué rasgos tuvo la unión de Portugal con Castilla en 1580? ¿Qué efectos tuvo Lepanto a corto y a largo plazo según las fuentes? ¿Cuántas bancarrotas declaró Felipe II según cada fuente y cómo se explica la diferencia?',
        quotes=[Q('es_felipe2','logrando una unión dinástica que duró sesenta años'), Q('en_lepanto','Venice was forced to accept loser\'s terms in spite of the victory at Lepanto.')]))
    return P

def problems(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    return [dict(role='worked', problem_type='NUMERICAL',
        prompt='Una fuente dice que de la Armada de 1588 regresaron a España 87 barcos, «unas dos terceras partes de la flota». La misma fuente da 130 barcos al zarpar y, más adelante, habla de 137 navíos españoles; otra fuente da 137. Calcule qué porcentaje de la flota representan los 87 barcos si se toma 130 como total, comparándolo con dos tercios (66,7 %) y con lo que resultaría tomando 137.',
        expected='66.9', quotes=[Q('es_armada','87 barcos —unas dos terceras partes de la flota— regresaron a España'), Q('en_armada','leaving 137 ships that sailed for the English Channel')],
        method='Cálculo de una proporción y contraste con una fracción declarada',
        solution=dict(given=[dict(symbol='r',value=87,unit='dimensionless',meaning='barcos que regresaron'),dict(symbol='N_1',value=130,unit='dimensionless',meaning='flota según la primera cifra'),dict(symbol='N_2',value=137,unit='dimensionless',meaning='flota según la segunda cifra')],
          unknown='El porcentaje de barcos que regresaron con cada total y su distancia a dos tercios.',
          model=[dict(name='Porcentaje con el total N',latex='p(N) = 100\\,\\frac{r}{N}',symbolic='100*r/N')],
          assumptions=['Se compara cada porcentaje con 100·2/3 = 66,67 %, la fracción que dice el texto.','La frase «unas dos terceras partes» es aproximada; el resultado solo permite descartar la cifra que se aleje mucho de ella.'],
          development=['Un porcentaje más cercano a 66,67 % es más compatible con la frase «unas dos terceras partes».'],
          steps=[dict(text='Con 130 barcos',equation='p(130) = 100 \\cdot 87/130',expression='100*87/130',expected=66.9231,unit='dimensionless'),
                 dict(text='Con 137 barcos',equation='p(137) = 100 \\cdot 87/137',expression='100*87/137',expected=63.5036,unit='dimensionless')],
          result='Con 130 barcos regresó el 66,9 % de la flota, casi exactamente dos tercios; con 137 sería el 63,5 %, algo menos de dos tercios.',
          interpretation='La frase «unas dos terceras partes» encaja mejor con 130 barcos que con 137. Eso no demuestra que 130 sea la cifra correcta, porque la otra fuente habla de 137, pero sugiere que la primera fuente usó 130 de manera consistente.',
          limitations=['«Dos terceras partes» es una expresión aproximada: 63,5 % también podría redondearse así. El cálculo sirve para ordenar la plausibilidad, no para resolver la discrepancia.'],
          mistakes=['Concluir que 130 es el dato verdadero porque encaja con una fracción redondeada, o dividir 87 por el número de barcos de guerra y no por el de toda la flota.']))]
